SantosLevelerAudioProcessorEditor::SantosLevelerAudioProcessorEditor(SantosLevelerAudioProcessor&p):AudioProcessorEditor(&p),processor(p),history(p),inputMeter(p,MeterComponent::Source::input,"INPUT",cyan),outputMeter(p,MeterComponent::Source::output,"OUTPUT",green),targetAttachment(p.apvts,"target",targetKnob),gateAttachment(p.apvts,"gate",gateKnob),speedAttachment(p.apvts,"speed",speedKnob),detectAttachment(p.apvts,"detect",detectKnob),lookaheadAttachment(p.apvts,"lookahead",lookaheadKnob),holdAttachment(p.apvts,"hold",holdKnob),releaseAttachment(p.apvts,"release",releaseKnob),peakThresholdAttachment(p.apvts,"peakThreshold",peakThresholdKnob),rangeDownAttachment(p.apvts,"rangeDown",rangeDownSlider),rangeUpAttachment(p.apvts,"rangeUp",rangeUpSlider),outputAttachment(p.apvts,"output",outputSlider),bypassAttachment(p.apvts,"bypass",bypassButton){setLookAndFeel(&lookAndFeel);setSize(1152,768);setResizable(true,true);setResizeLimits(960,640,1920,1280);titleLabel.setText("SANTOS LEVELER",juce::dontSendNotification);styleLabel(titleLabel,34,text,juce::Justification::centredLeft);addAndMakeVisible(titleLabel);subtitleLabel.setText("VOICE AUTO LEVEL RIDER",juce::dontSendNotification);styleLabel(subtitleLabel,13,muted,juce::Justification::centredLeft);addAndMakeVisible(subtitleLabel);configureKnob(gateKnob,gateLabel,"GATE"," dB",1,cyan);configureKnob(targetKnob,targetLabel,"TARGET"," dB",1,lime);configureKnob(speedKnob,speedLabel,"SPEED"," ms",0,cyan);configureKnob(detectKnob,detectLabel,"DETECT"," ms",0,cyan);configureKnob(lookaheadKnob,lookaheadLabel,"LOOKAHEAD"," ms",0,cyan);configureKnob(holdKnob,holdLabel,"HOLD"," ms",0,cyan);configureKnob(releaseKnob,releaseLabel,"RELEASE"," ms",0,cyan);configureKnob(peakThresholdKnob,peakThresholdLabel,"PEAK"," dBFS",1,magenta);configureFader(rangeDownSlider,rangeDownLabel,"RANGE DOWN"," dB",1,cyan);configureFader(rangeUpSlider,rangeUpLabel,"RANGE UP"," dB",1,yellow);configureFader(outputSlider,outputLabel,"OUTPUT"," dB",1,green);configureDevButton(bypassButton,"BYPASS");bypassButton.setClickingTogglesState(true);configureDevButton(export30Button,"EXPORT 30s");configureDevButton(export60Button,"EXPORT 60s");export30Button.onClick=[this]{exportHistoryCsv(30);};export60Button.onClick=[this]{exportHistoryCsv(60);};addAndMakeVisible(history);addAndMakeVisible(inputMeter);addAndMakeVisible(outputMeter);startTimerHz(30);}
