void SantosLevelerAudioProcessorEditor::exportHistoryCsv(int seconds){
 const auto samplesPerSecond=60;const auto maxPoints=(std::size_t)(seconds*samplesPerSecond);const auto pts=processor.getHistory().copyLatest(maxPoints);if(pts.empty())return;
 juce::String csv;csv<<"# SANTOS LEVELER DEVELOPMENT TELEMETRY V2\n";csv<<"# exported="<<juce::Time::getCurrentTime().toISO8601(true)<<"\n";csv<<"# requested_seconds="<<seconds<<"\n";csv<<"# sample_rate_hz=60\n";
 csv<<"# gate_db="<<juce::String(pv(processor,"gate"),2)<<"\n";csv<<"# target_db="<<juce::String(pv(processor,"target"),2)<<"\n";csv<<"# speed_ms="<<juce::String(pv(processor,"speed"),2)<<"\n";csv<<"# detect_ms="<<juce::String(pv(processor,"detect"),2)<<"\n";csv<<"# lookahead_ms="<<juce::String(pv(processor,"lookahead"),2)<<"\n";csv<<"# hold_ms="<<juce::String(pv(processor,"hold"),2)<<"\n";csv<<"# release_ms="<<juce::String(pv(processor,"release"),2)<<"\n";csv<<"# peak_threshold_dbfs="<<juce::String(pv(processor,"peakThreshold"),2)<<"\n";csv<<"# range_down_db="<<juce::String(pv(processor,"rangeDown"),2)<<"\n";csv<<"# range_up_db="<<juce::String(pv(processor,"rangeUp"),2)<<"\n";csv<<"# output_db="<<juce::String(pv(processor,"output"),2)<<"\n";
 csv<<"time_sec,input_aligned_db,fast_db,slow_db,control_db,raw_rider_db,gate_active,requested_rider_db,effective_rider_db,applied_rider_db,peak_envelope_db,peak_requested_reduction_db,peak_applied_db,output_db\n";
 const auto count=pts.size();for(std::size_t i=0;i<count;++i){const auto time=(static_cast<double>(i)-static_cast<double>(count-1))/60.0;const auto&p=pts[i];csv<<juce::String(time,4)<<","<<juce::String(p.inputDb,4)<<","<<juce::String(p.fastDb,4)<<","<<juce::String(p.slowDb,4)<<","<<juce::String(p.controlDb,4)<<","<<juce::String(p.rawRiderDb,4)<<","<<(p.gateActive?"1":"0")<<","<<juce::String(p.requestedRiderDb,4)<<","<<juce::String(p.effectiveRiderDb,4)<<","<<juce::String(p.riderDb,4)<<","<<juce::String(p.peakEnvelopeDb,4)<<","<<juce::String(p.peakReductionDb,4)<<","<<juce::String(p.peakDb,4)<<","<<juce::String(p.outputDb,4)<<"\n";}
 const auto stamp=juce::Time::getCurrentTime().formatted("%Y%m%d_%H%M%S");const auto name="SANTOS_LEVELER_V2_"+juce::String(seconds)+"s_"+stamp+".csv";auto start=juce::File::getSpecialLocation(juce::File::userDocumentsDirectory).getChildFile(name);exportFileChooser=std::make_unique<juce::FileChooser>("Export SANTOS LEVELER telemetry V2",start,"*.csv");exportFileChooser->launchAsync(juce::FileBrowserComponent::saveMode|juce::FileBrowserComponent::canSelectFiles|juce::FileBrowserComponent::warnAboutOverwriting,[csv](const juce::FileChooser&chooser){auto f=chooser.getResult();if(f!=juce::File{})f.replaceWithText(csv);});
}

void SantosLevelerAudioProcessorEditor::paint(juce::Graphics&g){g.fillAll(bg);auto sx=(float)getWidth()/1536.f,sy=(float)getHeight()/1024.f,s=juce::jmin(sx,sy);auto out=getLocalBounds().toFloat().reduced(4*s);juce::ColourGradient fg(juce::Colour(0xff35454f),out.getTopLeft(),juce::Colour(0xff040608),out.getBottomRight(),false);fg.addColour(.38,juce::Colour(0xff172229));g.setGradientFill(fg);g.fillRoundedRectangle(out,14*s);g.setColour(juce::Colour(0xff829099));g.drawRoundedRectangle(out.reduced(.5f*s),14*s,1*s);g.setColour(juce::Colours::black.withAlpha(.85f));g.drawRoundedRectangle(out.reduced(5*s),9*s,2*s);auto head=juce::Rectangle<float>(10*sx,10*sy,1516*sx,80*sy);panel(g,head,5*s);auto ride=juce::Rectangle<float>(487*sx,28*sy,196*sx,43*sy);bool act=processor.getRiderActive();g.setColour((act?green:juce::Colour(0xff243038)).withAlpha(.26f));g.fillRoundedRectangle(ride,4*s);g.setColour(act?green:muted);g.setFont(juce::FontOptions(15*s));g.drawText(act?"AUTO RIDING":"IDLE",ride.toNearestInt().withTrimmedRight((int)(32*sx)),juce::Justification::centred);g.fillEllipse(ride.getRight()-24*sx,ride.getCentreY()-4.5f*s,9*s,9*s);panel(g,{20*sx,648*sy,1496*sx,190*sy},7*s);panel(g,{20*sx,848*sy,1496*sx,116*sy},7*s);g.setFont(juce::FontOptions(10*s));g.setColour(muted);g.drawText("SANTOS LEVELER v1.0.0",(int)(36*sx),(int)(986*sy),(int)(190*sx),(int)(18*sy),juce::Justification::centredLeft);g.setColour(cyan);g.drawText("AUTO LEVEL RIDER TECHNOLOGY",(int)(290*sx),(int)(986*sy),(int)(260*sx),(int)(18*sy),juce::Justification::centredLeft);g.setColour(muted);g.drawText("DESIGNED & DEVELOPED BY SANTOS",(int)(1210*sx),(int)(986*sy),(int)(290*sx),(int)(18*sy),juce::Justification::centredRight);}

