void SantosLevelerAudioProcessorEditor::HistoryComponent::paint(juce::Graphics&g){auto r=getLocalBounds().toFloat();panel(g,r,7);auto in=r.reduced(10);auto top=in.removeFromTop(38);auto stats=in.removeFromBottom(92);in.removeFromBottom(8);g.setColour(text);g.setFont(juce::FontOptions(14));g.drawText("LIVE RESPONSE",top.toNearestInt(),juce::Justification::centredLeft);const juce::Colour cs[]={cyan,yellow,magenta,green};const char*ns[]={"INPUT","RIDER","PEAK","OUTPUT"};auto leg=top.removeFromRight(430);for(int i=0;i<4;++i){auto it=leg.removeFromLeft(leg.getWidth()/(4-i));g.setColour(cs[i]);g.drawLine(it.getX()+4,it.getCentreY(),it.getX()+26,it.getCentreY(),2);g.setFont(juce::FontOptions(10));g.drawText(ns[i],it.withTrimmedLeft(32).toNearestInt(),juce::Justification::centredLeft);}auto chart=in;g.setColour(juce::Colour(0xff03080b));g.fillRoundedRectangle(chart,4);auto plot=chart.reduced(42,14);for(int i=0;i<=5;++i){auto y=plot.getY()+plot.getHeight()*i/5.f;g.setColour(juce::Colour(0xff24313a));g.drawHorizontalLine((int)y,plot.getX(),plot.getRight());g.setColour(muted);g.setFont(juce::FontOptions(9));g.drawText(juce::String(-12*i),(int)chart.getX()+2,(int)y-7,32,14,juce::Justification::centredRight);}auto pts=processor.getHistory().copyLatest(320);if(pts.size()>=2){auto ly=[&](float d){auto n=juce::jlimit(0.f,1.f,(d+60)/60);return plot.getBottom()-n*plot.getHeight();};auto gy=[&](float d){auto n=juce::jlimit(0.f,1.f,(d+12)/24);return plot.getBottom()-n*plot.getHeight();};auto path=[&](auto f){juce::Path p;for(size_t i=0;i<pts.size();++i){auto x=plot.getX()+plot.getWidth()*(float)i/(float)(pts.size()-1),y=f(pts[i]);if(i==0)p.startNewSubPath(x,y);else p.lineTo(x,y);}return p;};auto ip=path([&](const SantosHistoryPoint&p){return ly(p.inputDb);}),op=path([&](const SantosHistoryPoint&p){return ly(p.outputDb);}),rp=path([&](const SantosHistoryPoint&p){return gy(p.riderDb);}),pp=path([&](const SantosHistoryPoint&p){return gy(p.peakDb);});auto fill=[&](juce::Path p){p.lineTo(plot.getRight(),plot.getBottom());p.lineTo(plot.getX(),plot.getBottom());p.closeSubPath();return p;};g.setColour(cyan.withAlpha(.10f));g.fillPath(fill(ip));g.setColour(green.withAlpha(.12f));g.fillPath(fill(op));g.setColour(cyan);g.strokePath(ip,juce::PathStrokeType(1.8f));g.setColour(yellow);g.strokePath(rp,juce::PathStrokeType(2));g.setColour(magenta);g.strokePath(pp,juce::PathStrokeType(1.8f));g.setColour(green);g.strokePath(op,juce::PathStrokeType(1.8f));}const float vs[]={processor.getRiderDb(),pv(processor,"target"),pv(processor,"peakThreshold"),processor.getOutputMeterDb()};const char*sn[]={"RIDER","TARGET","PEAK","OUTPUT"};const char*sf[]={" dB"," dB"," dBFS"," dB"};const juce::Colour sc[]={yellow,lime,magenta,green};auto sw=stats.getWidth()/4;for(int i=0;i<4;++i){auto c=stats.withX(stats.getX()+sw*i).withWidth(sw);if(i){g.setColour(border);g.drawVerticalLine((int)c.getX(),c.getY()+14,c.getBottom()-14);}g.setColour(muted);g.setFont(juce::FontOptions(12));g.drawText(sn[i],c.withTrimmedTop(12).withHeight(18).toNearestInt(),juce::Justification::centred);g.setColour(sc[i]);g.setFont(juce::FontOptions(24));g.drawText(juce::String(vs[i],1)+sf[i],c.withTrimmedTop(35).toNearestInt(),juce::Justification::centredTop);}if(processor.hasHostTransport()&&!processor.getTransportPlaying()){g.setColour(juce::Colour(0xaa03070a));g.fillRoundedRectangle(chart,4);g.setColour(text);g.drawText("PAUSED",chart.toNearestInt(),juce::Justification::centred);}}

void SantosLevelerAudioProcessorEditor::MeterComponent::paint(juce::Graphics&g){auto db=source==Source::input?processor.getInputMeterDb():processor.getOutputMeterDb();auto r=getLocalBounds().toFloat();panel(g,r,7);g.setColour(colour);g.setFont(juce::FontOptions(14));g.drawText(label,0,16,getWidth(),20,juce::Justification::centred);g.setFont(juce::FontOptions(21));g.drawText(juce::String(db,1)+" dB",0,42,getWidth(),28,juce::Justification::centred);auto ma=r.reduced(20,86);ma.removeFromBottom(32);bool left=source==Source::input;auto scale=left?ma.removeFromLeft(26):ma.removeFromRight(26);ma.reduce(6,0);auto gap=juce::jmax(6.f,ma.getWidth()*.08f),bw=(ma.getWidth()-gap)/2;auto n=juce::jlimit(0.f,1.f,(db+60)/60);for(int ch=0;ch<2;++ch){auto bar=juce::Rectangle<float>(ma.getX()+(bw+gap)*ch,ma.getY(),bw,ma.getHeight());g.setColour(juce::Colours::black);g.fillRoundedRectangle(bar.expanded(2),3);float gh=2,sh=(bar.getHeight()-gh*33)/34;for(int i=0;i<34;++i){auto ln=(float)(i+1)/34,yy=bar.getBottom()-(i+1)*sh-i*gh;auto seg=juce::Rectangle<float>(bar.getX(),yy,bar.getWidth(),sh);auto led=meterCol(colour,ln);g.setColour(led.withAlpha(ln<=n?.95f:.08f));g.fillRoundedRectangle(seg,1);}}g.setFont(juce::FontOptions(9));for(int i=0;i<=5;++i){auto y=scale.getY()+scale.getHeight()*i/5.f;g.setColour(muted);g.drawText(juce::String(-12*i),scale.withY(y-7).withHeight(14).toNearestInt(),left?juce::Justification::centredRight:juce::Justification::centredLeft);}g.setColour(muted);g.drawText("RMS",0,getHeight()-28,getWidth(),16,juce::Justification::centred);}
